<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Connection, Delete, Refresh, Setting, Warning } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, apiErrorMessage, ensureCsrf } from '../services/api'
import { authStore } from '../stores/auth'
import type { AutoReplyAttempt, AutoReplyAttemptStatus, AutoReplyPolicy, BrowserDevice, BrowserUnreadObservation, ConnectorActionLease, ConnectorActionTask, ConnectorCapability, ConnectorOfflineDrill, ConnectorProductionApproval, ConnectorValidationCase, UnmatchedJobGroup } from '../types'

type RuntimeState = 'RUNNING'|'REVIEW'|'PAUSED'|'OFFLINE'|'DISABLED'|'ERROR'
const policies=ref<AutoReplyPolicy[]>([]),attempts=ref<AutoReplyAttempt[]>([]),devices=ref<BrowserDevice[]>([]),observations=ref<BrowserUnreadObservation[]>([]),unmatchedJobGroups=ref<UnmatchedJobGroup[]>([]),capabilities=ref<ConnectorCapability[]>([]),validationCases=ref<ConnectorValidationCase[]>([]),actionTasks=ref<ConnectorActionTask[]>([]),actionLeases=ref<ConnectorActionLease[]>([]),productionApprovals=ref<ConnectorProductionApproval[]>([]),offlineDrills=ref<ConnectorOfflineDrill[]>([])
const router=useRouter()
const loading=ref(true),saving=ref(false),recalculating=ref(false),matchingKey=ref(''),awayActionId=ref(''),errorMessage=ref(''),dialogOpen=ref(false),editing=ref<AutoReplyPolicy>()
const matchSelections=reactive<Record<string,string>>({})
const activeTab=ref('accounts'),attemptStatusFilter=ref(''),attemptAccountFilter=ref('')
const canManage=computed(()=>authStore.state.user?.role!=='RECRUITER')
const form=reactive({enabled:false,awayMode:'TEMPORARY',awayEndsAt:'',autoSendEnabled:false,responseTimeoutMinutes:120,dailyLimit:20,minimumIntervalSeconds:180,sendingWindowStart:'09:00:00',sendingWindowEnd:'21:00:00',timezone:'Asia/Shanghai',maxConsecutiveFailures:3,replyTemplate:''})
const statusLabels:Record<AutoReplyAttemptStatus,string>={CLAIMED:'处理中',PENDING_REVIEW:'待人工审核',SENT:'已发送',FAILED:'失败',SKIPPED:'已跳过'}
const runtimeMeta:Record<RuntimeState,{label:string,type:'success'|'warning'|'danger'|'info'}>={RUNNING:{label:'自动运行中',type:'success'},REVIEW:{label:'等待人工审核',type:'warning'},PAUSED:{label:'安全暂停',type:'danger'},OFFLINE:{label:'设备未在线',type:'danger'},DISABLED:{label:'策略未启用',type:'info'},ERROR:{label:'账号能力异常',type:'danger'}}
function activeDevice(id:string){return devices.value.find(x=>x.accountId===id&&x.status==='ACTIVE')}
function accountReady(x:AutoReplyPolicy){return x.accountStatus==='ACTIVE'&&['CONNECTED','DEGRADED'].includes(x.connectionStatus)&&(x.monitorOnly||x.messageSendCapable)}
function isSafeMonitoringDevice(x?:BrowserDevice){return x?.runtimeState==='PAUSED'&&/^只监测：/.test(x.stopReason||'')}
function runtimeState(x:AutoReplyPolicy):RuntimeState{if(!x.awayActive)return'DISABLED';if(!accountReady(x))return'ERROR';if(x.monitorOnly)return'REVIEW';if(x.pausedUntil&&new Date(x.pausedUntil)>new Date())return'PAUSED';const d=activeDevice(x.accountId);if(!d||['OFFLINE','DISABLED'].includes(d.runtimeState))return'OFFLINE';if(d.runtimeState==='PAUSED'&&!isSafeMonitoringDevice(d))return'PAUSED';return x.autoSendEnabled?'RUNNING':'REVIEW'}
const runtimeAccounts=computed(()=>policies.value.map(policy=>({policy,state:runtimeState(policy),device:activeDevice(policy.accountId)})))
const attentionAccounts=computed(()=>runtimeAccounts.value.filter(x=>['PAUSED','OFFLINE','ERROR'].includes(x.state)))
const activeObservations=computed(()=>observations.value.filter(x=>x.unread))
const draftReadiness=computed(()=>({ready:activeObservations.value.filter(x=>x.draftQualification==='KNOWLEDGE_READY').length,blocked:activeObservations.value.filter(x=>x.draftQualification==='KNOWLEDGE_BLOCKED').length,unmatched:activeObservations.value.filter(x=>x.draftQualification==='JOB_UNMATCHED').length}))
const completedObservations=computed(()=>observations.value.filter(x=>!x.unread&&x.resolutionStatus!=='UNRESOLVED').slice(0,20))
const dailyTabs=computed(()=>[
  {id:'accounts',name:'值守设置',desc:'等待时间与接待内容'},
  {id:'observations',name:'待审草稿',desc:`${activeObservations.value.length} 个未读会话`},
  {id:'attempts',name:'处理记录',desc:'结果与跳过原因'},
])
const stats=computed(()=>({total:policies.value.length,running:runtimeAccounts.value.filter(x=>x.state==='RUNNING').length,attention:attentionAccounts.value.length,sentToday:policies.value.reduce((n,x)=>n+x.sentToday,0),online:devices.value.filter(x=>x.status==='ACTIVE'&&(x.runtimeState==='RUNNING'||isSafeMonitoringDevice(x))).length}))
const uncertainDrafts=computed(()=>observations.value.filter(x=>x.fillStatus==='UNKNOWN').length)
function deviceNeedsAttention(x:BrowserDevice){return x.runtimeState==='OFFLINE'||(x.runtimeState==='PAUSED'&&!isSafeMonitoringDevice(x))}
const runtimeWarning=computed(()=>{const stopped=devices.value.filter(x=>x.status==='ACTIVE'&&deviceNeedsAttention(x)).length;if(!stopped&&!uncertainDrafts.value)return'';return`${stopped?`${stopped} 个招聘账号的浏览器任务已安全停止`:''}${stopped&&uncertainDrafts.value?'；':''}${uncertainDrafts.value?`${uncertainDrafts.value} 条草稿填写结果不确定，系统不会自动重试`:''}`})
const filteredAttempts=computed(()=>attempts.value.filter(x=>(!attemptStatusFilter.value||x.status===attemptStatusFilter.value)&&(!attemptAccountFilter.value||x.accountId===attemptAccountFilter.value)))
async function load(){loading.value=true;errorMessage.value='';try{const [p,a,d,o,g,c,v,t,l,r,f]=await Promise.all([api.get<AutoReplyPolicy[]>('/auto-replies/policies'),api.get<AutoReplyAttempt[]>('/auto-replies/attempts'),api.get<BrowserDevice[]>('/local-connector/devices'),api.get<BrowserUnreadObservation[]>('/local-connector/observations'),api.get<UnmatchedJobGroup[]>('/local-connector/observations/unmatched-job-groups'),api.get<ConnectorCapability[]>('/local-connector/capabilities'),api.get<ConnectorValidationCase[]>('/local-connector/validation-cases'),api.get<ConnectorActionTask[]>('/local-connector/action-tasks'),api.get<ConnectorActionLease[]>('/local-connector/action-leases'),api.get<ConnectorProductionApproval[]>('/local-connector/production-approvals'),api.get<ConnectorOfflineDrill[]>('/local-connector/offline-drills')]);policies.value=p.data;attempts.value=a.data;devices.value=d.data;observations.value=o.data;unmatchedJobGroups.value=g.data;capabilities.value=c.data;validationCases.value=v.data;actionTasks.value=t.data;actionLeases.value=l.data;productionApprovals.value=r.data;offlineDrills.value=f.data}catch(e){errorMessage.value=apiErrorMessage(e,'自动跟进配置加载失败')}finally{loading.value=false}}
function observationAge(x:BrowserUnreadObservation){return Math.max(0,Math.floor((Date.now()-Date.parse(x.firstSeenAt))/60000))}
const eligibilityLabel:Record<BrowserUnreadObservation['eligibilityStatus'],string>={OBSERVING:'等待超时',AWAY_INACTIVE:'托管未开启',SNAPSHOT_CONFIRMATION_REQUIRED:'等待页面再次确认',DETAIL_REQUIRED:'需复核会话',READY_FOR_REVIEW:'待人工确认',HR_REPLIED:'HR 已回复',HR_HANDLED:'已处理',APPROVED_DRAFT:'草稿已批准',REJECTED:'已拒绝',HUMAN_TAKEOVER:'人工接管'}
const draftQualificationLabel={JOB_UNMATCHED:'岗位未匹配',KNOWLEDGE_BLOCKED:'资料待完善',KNOWLEDGE_READY:'知识草稿就绪'} as const
const blockerLabels:Record<string,string>={JOB_TITLE_MISSING:'未识别岗位标题',ACTIVE_JOB_NOT_FOUND:'没有严格匹配的启用岗位',ACTIVE_JOB_AMBIGUOUS:'存在重复的启用岗位',COMPANY_KNOWLEDGE_UNAPPROVED:'企业知识未审核',COMPANY_INDUSTRY_MISSING:'企业行业未填写',COMPANY_SUMMARY_MISSING:'企业介绍未填写',VISIBLE_CAPTURE_UNVERIFIED:'页面采集资料未核对',OBSERVED_JOB_UNVERIFIED:'未读识别岗位未核对',JOB_KNOWLEDGE_UNAPPROVED:'岗位知识未审核',JOB_REPLY_SUMMARY_MISSING:'岗位回复简介未填写',JOB_NOT_ACTIVE:'岗位未启用'}
function draftQualificationType(x:BrowserUnreadObservation){return x.draftQualification==='KNOWLEDGE_READY'?'success':x.draftQualification==='JOB_UNMATCHED'?'danger':'warning'}
function openDraftSource(x:BrowserUnreadObservation){router.push(x.draftBlockerCodes?.some(code=>code.startsWith('COMPANY_'))?'/organization':'/job-positions')}
function selectedMatch(group:UnmatchedJobGroup){return group.candidates.find(x=>x.id===matchSelections[group.groupKey])}
async function manualMatchGroup(group:UnmatchedJobGroup){const target=selectedMatch(group);if(!target)return;if(!target.knowledgeReady){ElMessage.warning('目标岗位资料尚未完整审核，暂不能关联');return}try{await ElMessageBox.confirm(`请核对：BOSS 观测到的岗位「${group.observedTitle}」确实对应系统岗位「${target.title}」。确认后将同时关联 ${group.conversations} 个匿名会话并重新生成草稿；不会操作 BOSS 页面。`,'确认批量岗位关联',{type:'warning',confirmButtonText:'标题无误，确认关联',cancelButtonText:'取消'});matchingKey.value=group.groupKey;await ensureCsrf();const {data}=await api.put<{matched:number;knowledgeReady:number}>('/local-connector/observations/manual-job-match',{observationIds:group.observationIds,jobPositionId:target.id,observedTitle:group.observedTitle,confirmedJobTitle:target.title,confirmed:true});ElMessage.success(`已关联 ${data.matched} 个会话，生成 ${data.knowledgeReady} 条知识草稿`);delete matchSelections[group.groupKey];await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'岗位批量关联失败'))}finally{matchingKey.value=''}}
async function recalculateDrafts(){recalculating.value=true;try{await ensureCsrf();const {data}=await api.post<{evaluated:number;knowledgeReady:number;blocked:number}>('/local-connector/observations/recalculate-drafts');ElMessage.success(`已重新评估 ${data.evaluated} 条：知识草稿 ${data.knowledgeReady} 条，回退草稿 ${data.blocked} 条`);await load()}catch(e){ElMessage.error(apiErrorMessage(e,'草稿资格重新评估失败'))}finally{recalculating.value=false}}
async function reviewObservation(x:BrowserUnreadObservation,decision:'APPROVED'|'REJECTED'|'HUMAN_TAKEOVER'){try{let content=x.draftContent||'',note='';if(decision==='APPROVED'){if(x.draftQualification!=='KNOWLEDGE_READY'){ElMessage.warning('企业与岗位资料尚未全部审核，当前草稿不能批准');openDraftSource(x);return}const source=`企业知识 v${x.draftCompanyKnowledgeVersion??'—'} · 岗位知识 v${x.draftJobKnowledgeVersion??'—'}`;const result=await ElMessageBox.prompt(`请逐字核对下方实际草稿。资料来源：${source}。可修改后批准；批准后仍不会自动发送，资料版本变化时本次批准会自动失效。`,`批准安全草稿 · ${source}`,{inputValue:content,inputType:'textarea',confirmButtonText:'已核对并批准',cancelButtonText:'取消',inputValidator:v=>String(v).trim().length>0||'草稿不能为空'});content=result.value}else{const result=await ElMessageBox.prompt(decision==='REJECTED'?'请填写拒绝原因':'请填写人工接管备注','处理未读会话',{confirmButtonText:'确认',cancelButtonText:'取消'});note=result.value}await ensureCsrf();await api.put(`/local-connector/observations/${x.id}/review`,{decision,content:decision==='APPROVED'?content:null,note});ElMessage.success(decision==='APPROVED'?'当前资料版本的草稿已批准，仍保持不发送':decision==='REJECTED'?'已拒绝草稿':'已标记人工接管');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'处理失败'))}}
const capabilityNames:Record<ConnectorCapability['capability'],string>={CHAT_LIST_READ:'读取未读列表',CONVERSATION_DETAIL_READ:'读取当前会话',JOB_LIST_READ:'读取岗位标题',SEND_MESSAGE:'发送消息',REQUEST_RESUME:'索要简历',EXCHANGE_WECHAT:'交换微信',EXCHANGE_PHONE:'交换电话'}
const capabilityStatuses:Record<ConnectorCapability['status'],string>={UNVERIFIED:'待真实账号验证',READ_ONLY_VERIFIED:'只读已验证',READY_FOR_MANUAL_TEST:'待单次人工测试',PRODUCTION_APPROVED:'已批准生产',BLOCKED:'已阻断'}
const validationStatuses:Record<ConnectorValidationCase['status'],string>={PREPARED:'准备中',WAITING_REAL_PAGE:'等待真实页面',MANUAL_TEST_RUNNING:'人工测试中',PASSED:'单次验收通过',FAILED:'验收失败',CANCELLED:'已取消'}
const leaseStatuses:Record<ConnectorActionLease['status'],string>={CLAIMED:'30 秒租约中',SUCCEEDED:'明确成功',FAILED:'明确失败',UNKNOWN:'结果未知已冻结',EXPIRED:'超时已冻结'}
const approvalStatuses:Record<ConnectorProductionApproval['status'],string>={PENDING_SECOND_APPROVAL:'等待第二位管理员',APPROVED:'低配额批准中',REVOKED:'已撤销',EXPIRED:'已到期'}
async function requestProductionApproval(x:ConnectorValidationCase){try{const result=await ElMessageBox.prompt('填写申请原因。系统默认限制为每小时 1 次、每日 3 次，并且仍不会接入页面执行器。','申请低配额试运行',{confirmButtonText:'提交第一人批准',cancelButtonText:'取消',inputValidator:v=>String(v).trim().length>=4||'请填写至少 4 个字'});await ensureCsrf();await api.post('/local-connector/production-approvals',{validationCaseId:x.id,hourlyLimit:1,dailyLimit:3,reason:result.value});ElMessage.success('已提交，必须由另一位管理员复核');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'提交生产批准失败'))}}
async function decideApproval(x:ConnectorProductionApproval,decision:'approve'|'revoke'){try{await ElMessageBox.confirm(decision==='approve'?'确认你不是申请人，并将该动作批准 24 小时？当前仍无页面执行器。':'确认立即撤销该动作批准？','生产门禁确认',{type:'warning',confirmButtonText:decision==='approve'?'第二人批准':'立即撤销',cancelButtonText:'取消'});await ensureCsrf();await api.post(`/local-connector/production-approvals/${x.id}/${decision}`,decision==='approve'?{durationHours:24}:undefined);ElMessage.success(decision==='approve'?'已完成双人批准，有效期 24 小时':'已撤销并锁定能力');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'生产门禁操作失败'))}}
async function emergencyStop(x:BrowserDevice){try{await ElMessageBox.confirm(`立即停止「${x.accountName}」并撤销该设备全部生产批准？此操作不会自动恢复。`,'账号紧急停止',{type:'error',confirmButtonText:'立即停止',cancelButtonText:'取消'});await ensureCsrf();await api.post(`/local-connector/devices/${x.id}/emergency-stop`);ElMessage.success('账号已停止，全部写能力已锁定');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'紧急停止失败'))}}
async function startValidation(x:ConnectorValidationCase){try{await ElMessageBox.confirm(`请确认你已在「${x.accountName}」对应的独立 Chrome 中打开允许测试的会话。开始后有 10 分钟，由 HR 手动完成一次「${capabilityNames[x.actionType]}」并核对页面结果。系统不会自动点击。`,'开始单次人工验收',{confirmButtonText:'开始 10 分钟验收',cancelButtonText:'取消',type:'warning'});await ensureCsrf();await api.post(`/local-connector/validation-cases/${x.id}/start`);ElMessage.success('人工验收窗口已开启，请在 BOSS 页面手动操作并核对结果');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'无法开始人工验收'))}}
async function completeValidation(x:ConnectorValidationCase,result:'PASSED'|'FAILED'){try{const prompt=await ElMessageBox.prompt(result==='PASSED'?'请描述页面出现的明确成功回执，不要填写候选人姓名、消息正文或联系方式。':'请描述失败、页面变化或风险提示，不要填写敏感信息。',result==='PASSED'?'登记验收通过':'登记验收失败',{confirmButtonText:'确认登记',cancelButtonText:'取消',inputType:'textarea',inputValidator:v=>String(v).trim().length>=4||'请填写至少 4 个字的脱敏说明'});await ensureCsrf();await api.post(`/local-connector/validation-cases/${x.id}/result`,{result,note:prompt.value});ElMessage.success(result==='PASSED'?'已记录单次人工验收；生产自动化仍保持关闭':'已记录失败并锁定该能力');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'登记验收结果失败'))}}
async function createAction(x:BrowserUnreadObservation,actionType:ConnectorActionTask['actionType']){try{await ensureCsrf();const {data}=await api.post<ConnectorActionTask>('/local-connector/action-tasks',{observationId:x.id,actionType});ElMessage.warning(data.reason);activeTab.value='actions';await load()}catch(e){ElMessage.error(apiErrorMessage(e,'登记受控动作失败'))}}
function duration(minutes:number){return minutes<60?`${minutes} 分钟`:`${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟`}
function openPolicy(x:AutoReplyPolicy){editing.value=x;Object.assign(form,{enabled:x.enabled,awayMode:x.awayMode==='IN_OFFICE'?'TEMPORARY':x.awayMode,awayEndsAt:x.awayEndsAt||new Date(Date.now()+2*3600000).toISOString(),autoSendEnabled:x.monitorOnly?false:x.autoSendEnabled,responseTimeoutMinutes:x.responseTimeoutMinutes,dailyLimit:x.dailyLimit,minimumIntervalSeconds:x.minimumIntervalSeconds,sendingWindowStart:x.sendingWindowStart,sendingWindowEnd:x.sendingWindowEnd,timezone:x.timezone,maxConsecutiveFailures:x.maxConsecutiveFailures,replyTemplate:x.replyTemplate});dialogOpen.value=true}
async function save(){if(!editing.value)return;if(editing.value.monitorOnly&&form.autoSendEnabled){ElMessage.error('当前为只监测测试模式，禁止开启自动回复');return}if(form.autoSendEnabled&&!form.enabled){ElMessage.error('开启自动发送前必须启用托管');return}saving.value=true;try{await ensureCsrf();const payload={...form,awayMode:form.enabled?form.awayMode:'IN_OFFICE',awayEndsAt:form.enabled?form.awayEndsAt:null};await api.put(`/auto-replies/policies/${editing.value.accountId}`,payload);ElMessage.success('账号托管策略已保存');dialogOpen.value=false;await load()}catch(e){ElMessage.error(apiErrorMessage(e,'策略保存失败'))}finally{saving.value=false}}
function formatDate(v?:string){return v?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function attemptType(s:AutoReplyAttemptStatus){return s==='SENT'?'success':s==='FAILED'?'danger':s==='SKIPPED'?'info':'warning'}
function quota(x:AutoReplyPolicy){return Math.min(100,Math.round(x.sentToday/Math.max(x.dailyLimit,1)*100))}
function deviceLabel(d?:BrowserDevice){return d?.runtimeState==='RUNNING'?'在线运行':isSafeMonitoringDevice(d)?'只监测中':d?.runtimeState==='PAUSED'?'已暂停':d?'离线':'未配对'}
async function setAway(x:AutoReplyPolicy,mode:'IN_OFFICE'|'TEMPORARY'|'AFTER_HOURS',hours=0){if(!x.configured){ElMessage.warning('请先由管理员配置该账号的托管策略');return}awayActionId.value=x.accountId;try{await ensureCsrf();await api.put(`/auto-replies/policies/${x.accountId}/away-mode`,{mode,endsAt:mode==='IN_OFFICE'?null:new Date(Date.now()+hours*3600000).toISOString()});ElMessage.success(mode==='IN_OFFICE'?'已结束托管，欢迎回来':'离开托管已开启');await load()}catch(e){ElMessage.error(apiErrorMessage(e,'托管状态更新失败'))}finally{awayActionId.value=''}}
async function createPairing(accountId:string){try{await ensureCsrf();const {data}=await api.post<{pairingToken:string}>('/local-connector/devices/pairings',{accountId});await ElMessageBox.alert(`连接令牌：${data.pairingToken}\n\n10 分钟内粘贴到本地 BOSS 连接器的配对命令中。关闭后不再展示。`,'一次性连接器令牌',{confirmButtonText:'我已安全保存'});await load()}catch(e){ElMessage.error(apiErrorMessage(e,'创建连接器令牌失败'))}}
async function revokeDevice(d:BrowserDevice){try{await ElMessageBox.confirm(`撤销 ${d.displayName}？本地连接器将立即无法同步或执行受控操作。`,'撤销本地连接器',{type:'warning'});await ensureCsrf();await api.delete(`/local-connector/devices/${d.id}`);ElMessage.success('连接器已撤销');await load()}catch(e){if(e!=='cancel')ElMessage.error(apiErrorMessage(e,'撤销失败'))}}
onMounted(load)
</script>

<template><div class="page-shell auto-page">
  <header class="page-heading"><div><span class="eyebrow">MESSAGE DUTY</span><h1>{{activeTab==='actions'?'连接器安全验收':'消息值守'}}</h1><p>{{activeTab==='actions'?'仅供管理员完成真实页面能力验证、批准与故障演练。':'配置离开期间的接待规则，审核安全草稿，并查看处理结果。'}}</p></div><div class="heading-actions"><el-button v-if="canManage" :type="activeTab==='actions'?'primary':'default'" :icon="Connection" @click="activeTab=activeTab==='actions'?'accounts':'actions'">{{activeTab==='actions'?'返回日常值守':'高级验收'}}</el-button><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div></header>
  <el-alert v-if="activeTab!=='actions'" class="safety-alert" type="warning" :closable="false" show-icon title="当前为安全测试：只监测并生成草稿，不会向 BOSS 自动发送。异常时系统会立即暂停。"/>
  <el-alert v-if="runtimeWarning" class="safety-alert" type="error" :closable="false" show-icon :title="runtimeWarning" description="请打开对应 Chrome Profile 和 BOSS 沟通页确认状态；未确认前保持停止。"/>
  <div v-if="loading" class="surface-panel"><el-skeleton :rows="8" animated/></div>
  <div v-else-if="errorMessage" class="surface-panel error-state"><el-icon><Warning/></el-icon><strong>自动跟进状态暂时无法加载</strong><span>{{errorMessage}}</span><el-button @click="load">重试</el-button></div>
  <template v-else>
    <nav v-if="activeTab!=='actions'" class="module-nav" aria-label="消息值守功能"><button v-for="t in dailyTabs" :key="t.id" :class="{active:activeTab===t.id}" @click="activeTab=t.id"><strong>{{t.name}}</strong><span>{{t.desc}}</span></button></nav>
    <div v-else class="advanced-notice"><span><strong>管理员工具</strong><small>{{capabilities.filter(x=>x.status==='READ_ONLY_VERIFIED').length}} 项只读能力已验证，所有页面写操作仍保持锁定。</small></span><el-button @click="activeTab='accounts'">退出高级验收</el-button></div>
    <section v-if="activeTab==='overview'" class="surface-panel quick-away"><div class="section-title-row"><div><h2>现在要离开吗？</h2><p>选择一个账号和离开时长，到期后服务端会自动停止托管。</p></div></div><div class="quick-away-list"><article v-for="x in policies" :key="x.accountId"><div><strong>{{x.accountName}}</strong><span v-if="x.awayActive">托管至 {{formatDate(x.awayEndsAt)}}</span><span v-else>当前在岗，不会自动接待</span></div><div><el-button v-if="x.awayActive" type="success" plain :loading="awayActionId===x.accountId" @click="setAway(x,'IN_OFFICE')">我已返回</el-button><template v-else><el-button :loading="awayActionId===x.accountId" @click="setAway(x,'TEMPORARY',1)">离开 1 小时</el-button><el-button type="primary" :loading="awayActionId===x.accountId" @click="setAway(x,'TEMPORARY',2)">离开 2 小时</el-button><el-button @click="setAway(x,'AFTER_HOURS',12)">下班托管</el-button></template></div></article></div></section>
    <template v-if="activeTab==='overview'">
      <div class="metrics"><article><span>自动运行账号</span><strong>{{stats.running}}<small> / {{stats.total}}</small></strong></article><article><span>需要关注</span><strong :class="{danger:stats.attention}">{{stats.attention}}</strong></article><article><span>今日已发送</span><strong>{{stats.sentToday}}</strong></article><article><span>在线浏览器</span><strong>{{stats.online}}</strong></article></div>
      <div class="overview-grid"><section class="surface-panel"><div class="section-title-row"><div><h2>账号运行状态</h2><p>先处理红色异常，再开启自动发送。</p></div><el-button text @click="activeTab='accounts'">管理策略</el-button></div><div v-if="!runtimeAccounts.length" class="empty">还没有可管理的招聘账号</div><article v-for="x in runtimeAccounts" :key="x.policy.accountId" class="health-row"><i>{{x.policy.accountName.slice(0,1)}}</i><div class="identity"><strong>{{x.policy.accountName}}</strong><span>{{x.policy.companyName}}</span></div><el-tag :type="runtimeMeta[x.state].type">{{runtimeMeta[x.state].label}}</el-tag><div class="quota"><span>今日额度 {{x.policy.sentToday}}/{{x.policy.dailyLimit}}</span><el-progress :percentage="quota(x.policy)" :show-text="false" :stroke-width="6"/></div><el-button v-if="canManage" text @click="openPolicy(x.policy)">配置</el-button></article></section>
      <aside class="surface-panel"><div class="section-title-row"><div><h2>需要处理</h2><p>{{attentionAccounts.length?'以下问题会阻止自动发送':'当前没有阻断项'}}</p></div></div><div v-if="!attentionAccounts.length" class="all-good"><b>✓</b><strong>链路状态正常</strong><small>仍会遵守限流与发送窗口</small></div><button v-for="x in attentionAccounts" :key="x.policy.accountId" class="attention" @click="activeTab=x.state==='OFFLINE'?'devices':'accounts'"><b></b><span><strong>{{x.policy.accountName}} · {{runtimeMeta[x.state].label}}</strong><small>{{x.device?.stopReason||'请检查账号能力、本地 Chrome 登录和连接器心跳状态'}}</small></span><em>处理 →</em></button></aside></div>
      <section class="surface-panel flow-panel"><div class="section-title-row"><div><h2>一次自动回复如何完成</h2><p>后端规则与短时租约是唯一权威；本地连接器只在明确授权后执行页面操作。</p></div></div><div class="flow"><article v-for="(x,i) in [['识别新消息','只采集必要会话状态'],['校验超时与规则','人工已回复则立即跳过'],['签发单次发送租约','检查时段、间隔与额度'],['页面发送并回执','DOM 异常或验证码停机']]" :key="i"><b>{{i+1}}</b><div><strong>{{x[0]}}</strong><span>{{x[1]}}</span></div></article></div></section>
    </template>
    <section v-if="activeTab==='observations'" class="surface-panel qualification-panel">
      <div class="section-title-row"><div><h2>草稿资料资格</h2><p>优先处理岗位关联；企业、岗位和采集资料全部通过后，才会使用知识草稿。</p></div><el-button :loading="recalculating" @click="recalculateDrafts">重新评估资料</el-button></div>
      <div class="draft-readiness"><span><b>{{draftReadiness.ready}}</b> 知识草稿就绪</span><span><b>{{draftReadiness.blocked}}</b> 资料待完善</span><span><b>{{draftReadiness.unmatched}}</b> 岗位未匹配</span><small>只更新后台草稿，不会操作 BOSS 页面</small></div>
      <div v-if="unmatchedJobGroups.length" class="job-match-workbench">
        <div class="workbench-heading"><div><h3>未匹配岗位批量处理</h3><p>相同账号和岗位标题已合并。只有 HR 明确确认后才会建立关联。</p></div><el-tag type="warning">{{unmatchedJobGroups.length}} 组待处理</el-tag></div>
        <article v-for="group in unmatchedJobGroups" :key="group.groupKey">
          <div class="match-source"><strong>{{group.observedTitle}}</strong><span>{{group.accountName}} · {{group.companyName}}</span><small>{{group.conversations}} 个匿名会话 · {{group.unreadCount}} 条未读</small></div>
          <div class="match-target"><el-select v-model="matchSelections[group.groupKey]" placeholder="选择确认对应的系统岗位" clearable><el-option v-for="job in group.candidates" :key="job.id" :label="`${job.title}${job.knowledgeReady?'':'（资料未就绪）'}`" :value="job.id" :disabled="!job.knowledgeReady"/></el-select><small v-if="selectedMatch(group)&&!selectedMatch(group)?.knowledgeReady">目标岗位资料尚未审核完成</small><small v-else>仅显示同一招聘账号下的启用岗位</small></div>
          <div class="match-actions"><el-button v-if="!group.candidates.some(x=>x.knowledgeReady)" @click="router.push('/job-positions')">先完善岗位资料</el-button><el-button v-else type="primary" :disabled="!selectedMatch(group)?.knowledgeReady" :loading="matchingKey===group.groupKey" @click="manualMatchGroup(group)">核对并批量关联</el-button></div>
        </article>
      </div>
      <div v-if="activeObservations.some(x=>x.draftQualification==='KNOWLEDGE_BLOCKED')" class="qualification-list"><article v-for="x in activeObservations.filter(v=>v.draftQualification==='KNOWLEDGE_BLOCKED')" :key="x.id"><div class="identity"><strong>{{x.observedJobTitle||`匿名会话 ${x.anonymousKey}`}}</strong><span>{{x.accountName}} · {{x.companyName}}</span></div><el-tag :type="draftQualificationType(x)">{{x.draftQualification?draftQualificationLabel[x.draftQualification]:'等待评估'}}</el-tag><div class="blocker-list"><span v-for="code in x.draftBlockerCodes||[]" :key="code">{{blockerLabels[code]||code}}</span></div><el-button text type="primary" @click="openDraftSource(x)">去完善资料</el-button></article></div>
    </section>
    <section v-if="activeTab==='observations'" class="surface-panel"><div class="section-title-row"><div><h2>真实未读观察与安全草稿</h2><p>仅上传岗位标题和不可逆摘要；草稿只保留在后台供 HR 审核，并由 HR 在 BOSS 页面自行发送。</p></div><el-tag type="warning">只读草稿</el-tag></div><el-empty v-if="!activeObservations.length" :image-size="72" description="当前没有待处理未读会话"/><div v-else class="observation-list"><article v-for="x in activeObservations" :key="x.id" :class="{expired:x.eligibilityStatus==='READY_FOR_REVIEW'}"><header><div class="identity"><strong>{{x.observedJobTitle||`匿名会话 ${x.anonymousKey}`}}</strong><span>{{x.accountName}} · {{x.companyName}} · {{x.observedJobTitle?`匿名会话 ${x.anonymousKey}`:'岗位未识别'}}</span></div><el-tag :type="x.eligibilityStatus==='READY_FOR_REVIEW'?'warning':x.eligibilityStatus==='APPROVED_DRAFT'?'success':'info'">{{eligibilityLabel[x.eligibilityStatus]}}</el-tag></header><div class="observation-metrics"><span><b>{{x.unreadCount}}</b> 条未读</span><span><b>{{duration(observationAge(x))}}</b> 持续未读</span><span><b>{{x.latestDirection==='INBOUND'?'候选人来信':x.latestDirection==='OUTBOUND'?'HR 已回复':'等待复核'}}</b> 最新方向</span></div><div v-if="x.draftContent" class="observation-draft"><div><el-tag size="small" :type="x.draftMode==='KNOWLEDGE'?'success':'warning'">{{x.draftMode==='KNOWLEDGE'?'已审核知识草稿':'通用回退草稿'}}</el-tag><small>{{x.draftReason}}</small></div><p>{{x.reviewedContent||x.draftContent}}</p><div class="draft-snapshot"><span>企业知识 v{{x.draftCompanyKnowledgeVersion??'—'}}</span><span>岗位知识 v{{x.draftJobKnowledgeVersion??'—'}}</span><span>生成于 {{formatDate(x.draftGeneratedAt)}}</span></div><strong>{{x.fillStatus==='UNKNOWN'?'历史草稿填写结果不确定，已停止且不会重试':x.fillStatus==='READY'?'草稿已批准，等待 HR 在 BOSS 中处理':x.reviewNote?.includes('自动失效')?x.reviewNote:'后台预备草稿 · 不会发送'}}</strong></div><div class="observation-actions"><template v-if="x.eligibilityStatus==='READY_FOR_REVIEW'"><el-button type="primary" :disabled="x.draftQualification!=='KNOWLEDGE_READY'" @click="reviewObservation(x,'APPROVED')">{{x.draftQualification==='KNOWLEDGE_READY'?'预览并批准':'资料未就绪'}}</el-button><el-button v-if="x.draftQualification!=='KNOWLEDGE_READY'" @click="openDraftSource(x)">完善资料</el-button><el-button @click="reviewObservation(x,'HUMAN_TAKEOVER')">人工接管</el-button><el-button type="danger" plain @click="reviewObservation(x,'REJECTED')">拒绝</el-button></template><el-dropdown v-if="canManage" trigger="click" @command="(v:string)=>createAction(x,v as ConnectorActionTask['actionType'])"><el-button plain>登记页面动作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="REQUEST_RESUME">索要简历</el-dropdown-item><el-dropdown-item command="EXCHANGE_WECHAT">交换微信</el-dropdown-item><el-dropdown-item command="EXCHANGE_PHONE">交换电话</el-dropdown-item><el-dropdown-item command="SEND_MESSAGE" :disabled="x.reviewStatus!=='APPROVED'||x.draftQualification!=='KNOWLEDGE_READY'">发送消息（需当前草稿已批准）</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><footer><span>详情复核 {{formatDate(x.detailVerifiedAt)}} · {{x.reviewNote||'无人工备注'}}</span><span>最近观测 {{formatDate(x.lastSeenAt)}}</span></footer></article></div><div v-if="completedObservations.length" class="completed-observations"><h3>最近已处理</h3><article v-for="x in completedObservations" :key="x.id"><div class="identity"><strong>{{x.observedJobTitle||`匿名会话 ${x.anonymousKey}`}}</strong><span>{{x.accountName}} · {{x.companyName}}</span></div><el-tag :type="x.resolutionStatus==='SOURCE_REPLACED'?'info':'success'">{{x.resolutionStatus==='SOURCE_REPLACED'?'旧设备记录已归档':x.resolutionStatus==='HR_SENT_AFTER_DRAFT'?'草稿后由 HR 发送':'HR 已回复'}}</el-tag><time>{{formatDate(x.resolvedAt)}}</time></article></div></section>
    <section v-else-if="activeTab==='accounts'" class="surface-panel"><div class="section-title-row"><div><h2>每个账号怎么监测</h2><p>设置 HR 离开时间和未回复阈值；当前只生成待审草稿，不会向 BOSS 发送。</p></div></div><div class="card-grid"><article v-for="x in policies" :key="x.accountId"><header><div class="identity"><strong>{{x.accountName}}</strong><span>{{x.companyName}}</span></div><el-tag :type="runtimeMeta[runtimeState(x)].type">{{runtimeMeta[runtimeState(x)].label}}</el-tag></header><div class="mode"><strong>{{x.monitorOnly?'只读监测':x.autoSendEnabled?'自动回复已允许':'发送前需审核'}}</strong><span>未回复 {{x.responseTimeoutMinutes}} 分钟后进入复核</span></div><el-alert v-if="x.monitorOnly" type="warning" :closable="false" title="当前只读监测：不需要消息发送权限，也不会填写或发送 BOSS 消息。"/><el-alert v-if="activeDevice(x.accountId)&&deviceNeedsAttention(activeDevice(x.accountId)!)" type="error" :closable="false" :title="activeDevice(x.accountId)?.stopReason||'浏览器设备已离线'"/><dl><div><dt>监测时间范围</dt><dd>{{x.sendingWindowStart.slice(0,5)}}–{{x.sendingWindowEnd.slice(0,5)}}</dd></div><div><dt>当前处理方式</dt><dd>{{x.monitorOnly?'仅进入待审草稿':'人工审核后处理'}}</dd></div></dl><el-button v-if="canManage" :icon="Setting" :disabled="!x.monitorOnly&&!x.messageSendCapable" @click="openPolicy(x)">修改监测设置</el-button><small v-else class="hint">如需修改，请联系招聘管理员。</small></article></div></section>
    <section v-else-if="activeTab==='devices'" class="surface-panel"><div class="section-title-row"><div><h2>本地 BOSS 连接器</h2><p>每个账号绑定一个独立 Chrome Profile；异常时必须人工介入。</p></div></div><div class="card-grid"><article v-for="x in policies" :key="x.accountId"><header><div class="identity"><strong>{{x.accountName}}</strong><span>{{x.companyName}}</span></div><el-tag :type="activeDevice(x.accountId)?.runtimeState==='RUNNING'?'success':'info'">{{deviceLabel(activeDevice(x.accountId))}}</el-tag></header><div v-if="activeDevice(x.accountId)" class="device"><Connection/><span><strong>{{activeDevice(x.accountId)?.displayName}}</strong><small>最后心跳 {{formatDate(activeDevice(x.accountId)?.lastHeartbeatAt)}}</small></span></div><div v-else class="unpaired">尚未配对本地连接器，无法检测消息或执行发送。</div><el-alert v-if="activeDevice(x.accountId)?.stopReason" type="warning" :closable="false" :title="activeDevice(x.accountId)?.stopReason"/><footer v-if="canManage"><el-button :icon="Connection" @click="createPairing(x.accountId)">{{activeDevice(x.accountId)?'重新配对':'生成连接令牌'}}</el-button><el-button v-if="activeDevice(x.accountId)" type="danger" plain :icon="Delete" @click="revokeDevice(activeDevice(x.accountId)!)">撤销</el-button></footer></article></div></section>
    <section v-else-if="activeTab==='actions'" class="surface-panel"><div class="section-title-row"><div><h2>页面能力与受控动作</h2><p>参考 CDP 工具的命令分层建立能力矩阵；没有真实页面验收的写操作只登记，不会下发浏览器。</p></div><el-tag type="warning">写操作锁定</el-tag></div><div class="capability-grid"><article v-for="x in capabilities" :key="x.id"><div class="identity"><strong>{{capabilityNames[x.capability]}}</strong><span>{{x.accountName}} · {{x.companyName}}</span></div><el-tag :type="x.status==='READ_ONLY_VERIFIED'?'success':x.status==='BLOCKED'?'danger':'warning'">{{capabilityStatuses[x.status]}}</el-tag><p>{{x.reason}}</p><time>{{formatDate(x.verifiedAt||x.updatedAt)}}</time></article></div><div class="validation-section"><div class="validation-heading"><div><h3>真实页面单次验收清单</h3><p>真实账号到位后按顺序人工检查。当前只生成动作预览，不点击、不输入、不发送。</p></div><el-tag type="warning">{{validationCases.filter(x=>x.status==='WAITING_REAL_PAGE').length}} 项等待页面</el-tag></div><el-empty v-if="!validationCases.length" :image-size="64" description="连接本地浏览器后生成验收清单"/><div v-else class="validation-grid"><article v-for="x in validationCases" :key="x.id"><header><div class="identity"><strong>{{capabilityNames[x.actionType]}}</strong><span>{{x.accountName}} · {{x.companyName}}</span></div><el-tag :type="x.status==='PASSED'?'success':x.status==='FAILED'?'danger':'warning'">{{validationStatuses[x.status]}}</el-tag></header><div class="validation-body"><strong>验收前必须确认</strong><ol><li v-for="item in x.prerequisites" :key="item">{{item}}</li></ol><strong>预期回执</strong><p>{{x.expectedResult}}</p><el-alert v-if="x.lastFailureReason" type="error" :closable="false" :title="x.lastFailureReason"/><div v-if="canManage&&(x.status==='PREPARED'||x.status==='MANUAL_TEST_RUNNING')" class="validation-actions"><el-button v-if="x.status==='PREPARED'" type="primary" @click="startValidation(x)">开始单次人工验收</el-button><template v-else><el-button type="success" @click="completeValidation(x,'PASSED')">页面结果明确成功</el-button><el-button type="danger" plain @click="completeValidation(x,'FAILED')">失败或结果不确定</el-button></template></div></div><footer>{{x.status==='MANUAL_TEST_RUNNING'?`验收窗口截止 ${formatDate(x.testExpiresAt)}`:x.completedAt?`完成于 ${formatDate(x.completedAt)}`:`准备于 ${formatDate(x.preparedAt)}`}}</footer></article></div></div><div class="action-queue"><h3>最近登记的动作</h3><el-empty v-if="!actionTasks.length" :image-size="64" description="尚未登记页面写操作"/><article v-for="x in actionTasks" :key="x.id"><div class="identity"><strong>{{capabilityNames[x.actionType]}}</strong><span>{{x.accountName}} · 匿名会话 {{x.anonymousKey}}</span></div><el-tag type="warning">{{x.status==='BLOCKED_UNVERIFIED'?'未验证阻断':'等待人工测试'}}</el-tag><p>{{x.reason}}</p><time>{{formatDate(x.createdAt)}}</time></article></div></section>
    <section v-else class="surface-panel"><div class="section-title-row attempts-head"><div><h2>发送记录</h2><p>查看每次发送租约结果，失败与跳过不计成功额度。</p></div><div class="filters"><el-select v-model="attemptAccountFilter" clearable placeholder="全部账号"><el-option v-for="x in policies" :key="x.accountId" :label="x.accountName" :value="x.accountId"/></el-select><el-select v-model="attemptStatusFilter" clearable placeholder="全部状态"><el-option v-for="(v,k) in statusLabels" :key="k" :label="v" :value="k"/></el-select></div></div><el-empty v-if="!filteredAttempts.length" :image-size="72" description="暂无符合条件的记录"/><div class="attempt-list"><article v-for="x in filteredAttempts" :key="x.id"><div class="identity"><strong>{{x.candidateName}}</strong><span>{{x.jobTitle}} · {{x.accountName}}</span></div><el-tag :type="attemptType(x.status)">{{statusLabels[x.status]}}</el-tag><div class="result"><strong>{{x.resultMessage||'等待处理结果'}}</strong><span>尝试 {{x.attemptCount}} 次 · {{formatDate(x.completedAt||x.createdAt)}}</span></div></article></div></section>
    <section v-if="activeTab==='actions'" class="surface-panel lease-panel"><div class="section-title-row"><div><h2>单次动作租约与回执</h2><p>只有生产批准能力才能取得 30 秒单次租约。当前连接器没有页面执行器，因此这里正常应为空。</p></div><el-tag type="info">协议待命</el-tag></div><el-empty v-if="!actionLeases.length" :image-size="64" description="暂无动作租约，所有写操作仍保持关闭"/><div v-else class="action-queue"><article v-for="x in actionLeases" :key="x.id"><div class="identity"><strong>{{capabilityNames[x.actionType]}}</strong><span>{{x.accountName}} · 匿名目标 {{x.targetDigest||'—'}}</span></div><el-tag :type="x.status==='SUCCEEDED'?'success':x.status==='CLAIMED'?'warning':'danger'">{{leaseStatuses[x.status]}}</el-tag><p>{{x.resultReason||`租约截止 ${formatDate(x.leaseUntil)}`}}</p><time>{{formatDate(x.completedAt||x.leasedAt)}}</time></article></div></section>
    <section v-if="activeTab==='actions'" class="surface-panel lease-panel"><div class="section-title-row"><div><h2>生产批准与低配额门禁</h2><p>真实页面验收通过后，由两位不同管理员依次批准；默认建议每小时 1 次、每日 3 次。</p></div><el-tag type="danger">页面执行器未接入</el-tag></div><div class="approval-request"><el-button v-for="x in validationCases.filter(v=>v.status==='PASSED'&&!productionApprovals.some(a=>a.deviceId===v.deviceId&&a.actionType===v.actionType&&['PENDING_SECOND_APPROVAL','APPROVED'].includes(a.status)))" :key="x.id" type="primary" plain @click="requestProductionApproval(x)">申请 {{capabilityNames[x.actionType]}} 低配额试运行</el-button></div><el-empty v-if="!productionApprovals.length" :image-size="64" description="暂无生产批准；所有页面写能力继续锁定"/><div v-else class="approval-grid"><article v-for="x in productionApprovals" :key="x.id"><header><div class="identity"><strong>{{capabilityNames[x.actionType]}}</strong><span>{{x.accountName}} · {{x.companyName}}</span></div><el-tag :type="x.status==='APPROVED'?'success':x.status==='PENDING_SECOND_APPROVAL'?'warning':'danger'">{{approvalStatuses[x.status]}}</el-tag></header><p>每小时 {{x.hourlyLimit}} 次 · 每日 {{x.dailyLimit}} 次 · {{x.reason}}</p><small>申请人 {{x.requestedBy}} · 批准人 {{x.approvedBy||'待另一位管理员'}} · 到期 {{formatDate(x.expiresAt)}}</small><footer v-if="canManage"><el-button v-if="x.status==='PENDING_SECOND_APPROVAL'" type="primary" @click="decideApproval(x,'approve')">作为第二人批准 24 小时</el-button><el-button v-if="x.status==='APPROVED'" type="danger" plain @click="decideApproval(x,'revoke')">立即撤销</el-button></footer></article></div></section>
    <section v-if="activeTab==='actions'&&canManage&&devices.some(x=>x.status==='ACTIVE')" class="surface-panel emergency-panel"><div><strong>账号级紧急停止</strong><span>出现验证码、风险提示、页面变化或结果不确定时立即使用。</span></div><el-button v-for="x in devices.filter(v=>v.status==='ACTIVE')" :key="x.id" type="danger" plain @click="emergencyStop(x)">停止 {{x.accountName}}</el-button></section>
    <section v-if="activeTab==='actions'" class="surface-panel lease-panel"><div class="section-title-row"><div><h2>离线执行器演练</h2><p>只在本地仿真页面验证四类动作的状态机、前后证据和回执；演练通过不会解锁真实页面能力。</p></div><el-tag type="info">FIXTURE ONLY</el-tag></div><el-empty v-if="!offlineDrills.length" :image-size="64" description="尚无离线演练记录；真实页面执行器仍未启用"/><div v-else class="drill-grid"><article v-for="x in offlineDrills" :key="x.id"><header><div class="identity"><strong>{{capabilityNames[x.actionType]}}</strong><span>{{x.accountName}} · 本地仿真证据</span></div><el-tag :type="x.outcome==='PASSED'?'success':'danger'">{{x.outcome==='PASSED'?'演练通过':'演练失败'}}</el-tag></header><dl><div><dt>执行前</dt><dd>{{x.beforeDigest}}</dd></div><div><dt>执行后</dt><dd>{{x.afterDigest}}</dd></div><div><dt>回执</dt><dd>{{x.receiptDigest}}</dd></div></dl><p v-if="x.failureReason">{{x.failureReason}}</p><time>{{formatDate(x.createdAt)}} · {{x.evidenceSource}}</time></article></div></section>
  </template>
  <el-dialog v-model="dialogOpen" :title="`${editing?.accountName??''} · ${editing?.monitorOnly?'未回复监测设置':'回复设置'}`" width="680px">
    <el-alert v-if="editing?.monitorOnly" type="warning" :closable="false" show-icon title="只读监测不会填写或发送消息；安全草稿由已审核的企业与岗位资料生成。"/>
    <el-alert v-else type="info" :closable="false" show-icon title="建议首次先人工审核，确认识别和回复都正常后再允许自动发送。"/>
    <el-form label-position="top" class="policy-form">
      <div class="form-grid">
        <el-form-item label="启用离开监测"><el-switch v-model="form.enabled"/><small class="hint">关闭后所有会话只保留观察，不进入待审草稿。</small></el-form-item>
        <el-form-item v-if="form.enabled" label="监测结束时间"><el-date-picker v-model="form.awayEndsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ" placeholder="选择 HR 返回时间"/></el-form-item>
        <el-form-item label="未回复多久后复核"><el-input-number v-model="form.responseTimeoutMinutes" :min="5" :max="10080"/><small class="hint">达到时间后仍需确认最后消息来自候选人。</small></el-form-item>
        <el-form-item v-if="!editing?.monitorOnly" label="允许自动回复"><el-switch v-model="form.autoSendEnabled" :disabled="!form.enabled"/></el-form-item>
        <el-form-item v-if="!editing?.monitorOnly" label="每天最多回复"><el-input-number v-model="form.dailyLimit" :min="1" :max="200"/></el-form-item>
        <el-form-item v-if="!editing?.monitorOnly" label="开始时间"><el-time-picker v-model="form.sendingWindowStart" value-format="HH:mm:ss" format="HH:mm"/></el-form-item>
        <el-form-item v-if="!editing?.monitorOnly" label="结束时间"><el-time-picker v-model="form.sendingWindowEnd" value-format="HH:mm:ss" format="HH:mm"/></el-form-item>
      </div>
      <el-form-item v-if="!editing?.monitorOnly" label="回复内容"><el-input v-model="form.replyTemplate" type="textarea" :rows="4" maxlength="1000" show-word-limit/><small class="hint">可以使用 {jobTitle} 自动带入职位名称。请只用于确认收到，不承诺薪资、录用或面试结果。</small></el-form-item>
    </el-form>
    <template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存监测设置</el-button></template>
  </el-dialog>
</div></template>

